import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const root = process.cwd();
const srcRoot = join(root, 'artifacts/therassistant-inventory/src');

// This contract is also used as the human-authored CI verification trigger
// after guarded refactor commits generated by GitHub Actions.
function walk(dir) {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return walk(path);
    return /\.(ts|tsx)$/.test(name) ? [path] : [];
  });
}

const required = [
  'artifacts/therassistant-inventory/src/lib/supabase-client.ts',
  'artifacts/therassistant-inventory/src/auth/auth-context.tsx',
  'artifacts/therassistant-inventory/src/auth/tenant-context.tsx',
];

const failures = [];
for (const file of required) {
  if (!existsSync(join(root, file))) failures.push(`missing required production auth module: ${file}`);
}

const forbidden = [
  ['DEMO_TENANT_NAME', /DEMO_TENANT_NAME/],
  ['getDemoTenantId', /getDemoTenantId/],
  ['createDemoClient', /createDemoClient/],
  ['demoSelect', /\bdemoSelect\b/],
  ['demoInsert', /\bdemoInsert\b/],
  ['demoUpdate', /\bdemoUpdate(?:Exact)?\b/],
  ['demoRpc', /\bdemoRpc\b/],
  ['demoTenant', /\bdemoTenant\b/],
  ['demo route', /path=["']\/demo["']/],
  ['DEMO PRACTICE', /DEMO PRACTICE/],
  ['SYNTHETIC DEMO DATA', /SYNTHETIC DEMO DATA/],
];

for (const file of walk(srcRoot)) {
  const rel = relative(root, file);
  // Patient-facing portal identity/security is intentionally a separate phase.
  if (rel.includes('/domains/portal/')) continue;
  const text = readFileSync(file, 'utf8');
  for (const [label, pattern] of forbidden) {
    if (pattern.test(text)) failures.push(`${rel}: forbidden production demo marker: ${label}`);
  }
}

if (failures.length) {
  console.error('Production auth contract failed:');
  for (const failure of failures) console.error(`- ${failure}`);
  process.exit(1);
}

console.log('Production auth contract passed.');
